 export const $ZodString: core.$constructor<$ZodString> = /*@__PURE__*/ core.$constructor("$ZodString", (inst, def) => {
   $ZodType.init(inst, def);
-  inst._zod.pattern = [...(inst?._zod.bag?.patterns ?? [])].pop() ?? regexes.string(inst._zod.bag);
+  // last wins, as `[...patterns].pop()` did, without materializing the array
+  let lastPattern: RegExp | undefined;
+  const patterns = inst._zod.bag?.patterns;
+  if (patterns) for (const p of patterns) lastPattern = p;
+  inst._zod.pattern = lastPattern ?? regexes.string(inst._zod.bag);
   inst._zod.parse = (payload, _) => {
     if (def.coerce)
       try {
@@ -3513,12 +3517,13 @@ export const $ZodEnum: core.$constructor<$ZodEnum> = /*@__PURE__*/ core.$constru
