- export const Page = () => (
-   <Container>
+ export const Page = (props: { children: HtmlEscapedString }) => (
+   <Container {...props}>
```

On the other hand, the following React counterpart compiles.

```ts
import React from "react";

const Container = (props: { children: React.ReactNode }) => (
  <div className="container">{props.children}</div>
);
