Fixture nodes from test.extend() shown as separate entries in test explorer tree

### Describe the bug

When using a builder pattern that wraps `test.extend('name', factory)` and test.projects is configured in `vitest.config.ts`, each fixture registered via `.extend()` appears as a separate node in the test explorer tree.

Minimal single-file repro:

```
import { describe, expect, it as baseIt, type TestAPI } from "vitest";

const createBuilder = <T>(api: TestAPI<T>): any => ({
  with: (fn: any, ...args: any[]) => createBuilder(fn(api, ...args)),
  build: () => api,
});

const extendWithDb = <T>(baseIt: TestAPI<T>) =>
  baseIt.extend("db", () => ({ query: () => "result" }));

const testContext = () => createBuilder(baseIt);

const it = testContext()
  .with(extendWithDb)
  .build();

describe('example', () => {
  it('should work', ({ db }: any) => {
    expect(db.query()).toBe('result');
  });
});
