describe.sequential('sequential suite', () => {
  test('test 1', async ({ task }) => {
    await delay(2000);
    expect(task.concurrent).toBeFalsy();
    expect(++count).toBe(1);
  });

  test('test 2', ({ task }) => {
    expect(task.concurrent).toBeFalsy();
    expect(++count).toBe(2);
  });
});
```

