import {
    ChildEntity, Column, DataSource, Entity,
    PrimaryGeneratedColumn, TableInheritance,
} from "typeorm"

class Meta {
    @Column({ type: String, nullable: true })
    note?: string
}

@Entity({ name: "with_embedded" })
@TableInheritance({ column: { type: String, name: "discriminator" } })
class WithEmbedded {
    @PrimaryGeneratedColumn()
    id!: number

    @Column(() => Meta)
    meta!: Meta
}

@ChildEntity()
class WithEmbeddedChild extends WithEmbedded {}

@Entity({ name: "without_embedded" })
@TableInheritance({ column: { type: String, name: "discriminator" } })
class WithoutEmbedded {
    @PrimaryGeneratedColumn()
    id!: number
}

@ChildEntity()
class WithoutEmbeddedChild extends WithoutEmbedded {}

const ds = new DataSource({
    type: "better-sqlite3",
