            async (result: Entity) => {
                if (!result) {
                    return result;
                }
                const transformer = new DocumentToEntityTransformer();
                const entity = transformer.transform(result, metadata);
                // Broadcast "Load" event
                await queryRunner.broadcaster.broadcast("Load", metadata, [
                    entity,
                ]);
                return entity;
            },
        );
}
