Bug: "multiple assignments to same column" error when eager loading relations that share column

### Issue description

When an entity has multiple `@OneToOne` relations sharing the same column (defined with both `@Column` and `@JoinColumn` decorators), eagerly loading these relations via `find()` with `relations: {}` option, then calling `save()` on the entity results in a PostgreSQL error: `multiple assignments to same column`.  This occurs even when; relations have `persistence: false` option, relations have `createForeignKeyConstraints: false`, the column is explicitly managed via `@Column` decorator.

### Expected Behavior

Since the relations have `persistence: false`, TypeORM should not attempt to persist them during `save()` operations, regardless of whether they were eagerly loaded or not.

### Actual Behavior

```
QueryFailedError: multiple assignments to same column "option_id"
```

The error occurs in the UPDATE statement generated by TypeORM when `save()` is called on an entity that was loaded with eager relations.

### Steps to reproduce

### 1. Define entities with shared column

```typescript
import {
    Entity,
    BaseEntity,
    PrimaryGeneratedColumn,
    Column,
    ManyToOne,
    OneToOne,
    JoinColumn,
    OneToMany,
} from 'typeorm';

@Entity()
export class OptionA extends BaseEntity {
    @PrimaryGeneratedColumn('increment')
    id: number;

    @OneToOne(() => MainEntity, (m) => m.optionA, { lazy: true })
    main: Promise<MainEntity | null>;
}

@Entity()
export class OptionB extends BaseEntity {
    @PrimaryGeneratedColumn('increment')
    id: number;

    @OneToOne(() => MainEntity, (m) => m.optionB, { lazy: true })
    main: Promise<MainEntity | null>;
}

@Entity()
export class RelatedEntity extends BaseEntity {
    @PrimaryGeneratedColumn('increment')
    id: number;

    @OneToMany(() => MainEntity, (m) => m.related, { lazy: true })
    mains: Promise<MainEntity[]>;

    @Column('boolean', { default: false })
    status: boolean;
}

@Entity()
export class MainEntity extends BaseEntity {
    @PrimaryGeneratedColumn('increment')
    id: number;

    // Column that multiple relations share
    @Column('integer', { nullable: true, name: 'option_id', unique: true })
    optionId: number | null;

    // Multiple relations pointing to the same column
    @OneToOne(() => OptionA, (a) => a.main, { 
        lazy: true, 
        createForeignKeyConstraints: false,
        persistence: false  // This should prevent the error, but doesn't when eager loaded
    })
    @JoinColumn({ name: 'option_id' })
    optionA: Promise<OptionA | null>;

    @OneToOne(() => OptionB, (b) => b.main, { 
        lazy: true, 
        createForeignKeyConstraints: false,
        persistence: false
    })
    @JoinColumn({ name: 'option_id' })
    optionB: Promise<OptionB | null>;

    @Column('integer', { name: 'related_id' })
    relatedId: number;

    @ManyToOne(() => RelatedEntity, (r) => r.mains, {
        lazy: true,
        onDelete: 'NO ACTION',
        onUpdate: 'NO ACTION',
    })
    @JoinColumn({ name: 'related_id' })
    related: Promise<RelatedEntity>;

    @Column('varchar', { default: '' })
    other: string;

    async updateRelatedStatus() {
        (await this.related).status = true;
        await this.save();  // This is where the error occurs
        await (await this.related).save();
    }
}
```

