increment\<Entity extends ObjectLiteral\>(entityClass: EntityTarget\<Entity\>, conditions: FindOptionsWhere\<Entity\>, propertyPath: keyof Entity, value: number | string): Promise<UpdateResult\>;

decrement\<Entity extends ObjectLiteral\>(entityClass: EntityTarget\<Entity\>, conditions: FindOptionsWhere\<Entity\>, propertyPath: keyof Entity, value: number | string): Promise\<UpdateResult\>;

