@Entity("threads")
class Thread extends BaseEntity {
    @PrimaryGeneratedColumn()
    public id: number;

    @Column("varchar")
    public name: string;

    @OneToMany((type) => Post, (comments) => comments.thread)
    public posts: Post[];
}

@Entity("posts")
class Post extends BaseEntity {
    @PrimaryGeneratedColumn()
    public id: number;

    @ManyToOne((type) => Thread, (thread) => thread.posts)
    public thread: Thread;
}

(async () => {
    let dbConn: Connection;

    try {
        dbConn = await createConnection({
            type: "mysql",
            host: "127.0.0.1",
            port: 3306,

            database: "database",
            password: "123",
            username: "root",

            synchronize: true,
            logging: true,
            entities: [Thread, Post],
        });

        const threadName = "Mega Thread";

        const thread = await Thread.create({ name: threadName }).save();
        const comment = await Post.create({ thread }).save();

        const test = await Post.find({
            relations: ["thread"],
            where: {
                thread: {
                    name: threadName,
                },
            },
        });

        console.log(test);
    } catch (error) {
        console.error(error.message);
    } finally {
        if (dbConn) {
            dbConn.close();
        }
    }
})();
